'use strict';
const state={playMode:location.hash.split('/')[1]||'blind',mapSpot:0,facet:'medical',resource:0,view:'overview',city:'shanghai',metric:'gdp',region:'all',search:'',compare:['shanghai','beijing','shenzhen'],weights:[30,25,20,10,15],scenario:'base',rate:4.5,year:2036};
const views={play:['探索游乐场','把城市，变成一场探索','从盲选到漫游，从生活试算到时间旅行，用不同方式认识十座城市。'],facets:['城市切面','城市的实力，落在日常里','从医疗、交通、文化到科教与休闲，看具体资源，也看生活中的取舍。'],overview:['城市总览','读懂中国的经济大城','点击地图或城市，探索经济体量背后的产业与生活。'],industry:['产业图谱','城市靠什么生长','从主导产业到产业链，观察十座城市的经济底色。'],living:['宜居实验室','适合你的城市，才是好城市','调整生活偏好，看看不同城市如何回应你的选择。'],history:['历史脉络','今天的城市，写在过去里','沿着历史节点，理解城市功能与空间格局的形成。'],future:['未来十年','向 2036 年，打开可能性','把驱动力、风险与增长假设放在一起，探索不同情景。'],sources:['数据与口径','每个数字，都有边界','区分统计事实、编辑判断与情景假设。']};
const $=s=>document.querySelector(s);const fmt=(v,d=2)=>Number(v).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const selected=()=>CITIES.find(c=>c.id===state.city);const filtered=()=>CITIES.filter(c=>(state.region==='all'||c.region===state.region)&&(!state.search||[c.name,c.en,...c.industry,c.tag,...(state.view==='facets'?Object.values(window.CITY_FACETS?.[c.name]||{}).flatMap(f=>[f.signature,f.headline,...f.resources.map(r=>r.name)]):[])].join(' ').toLowerCase().includes(state.search.toLowerCase())));let geography=null;
function profile(c){return {...c,...(window.PROFILES[c.name]||{})};}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function setCity(id){if(!CITIES.some(c=>c.id===id))throw new Error('城市不存在');state.city=id;state.mapSpot=0;state.resource=0;const keepFocus=state.view==='play'&&document.activeElement?.matches('[data-city]');render();if(keepFocus)document.querySelector('#play-body [data-city="'+id+'"]')?.focus({preventScroll:true});}
function setView(view){if(!views[view])throw new Error('视角不存在');state.view=view;if(view!=='play'&&filtered().length&&!filtered().some(c=>c.id===state.city))state.city=filtered()[0].id;state.resource=0;history.replaceState(null,'','#'+view+(view==='play'?'/'+state.playMode:''));render();}
function cityStrip(){return '<div class="city-strip" aria-label="选择城市">'+filtered().map(c=>`<button class="city-pill ${state.city===c.id?'selected':''}" data-city="${c.id}" aria-pressed="${state.city===c.id}">${c.name}</button>`).join('')+'</div>';}
function project(lon,lat){return [(lon-73)/63*720+25,(54-lat)/36*390+15];}
function geoPaths(){if(!geography)return '';return geography.features.map(f=>{const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return polys.map(poly=>'<path class="province" d="'+poly.map(ring=>ring.map((p,i)=>{const a=project(p[0],p[1]);return(i?'L':'M')+a.map(n=>n.toFixed(1)).join(',');}).join('')+'Z').join('')+'"/>').join('');}).join('');}
function map(){const enabled=new Set(filtered().map(c=>c.id));const offsets={shanghai:[29,-7],suzhou:[-54,-15],hangzhou:[-26,27],nanjing:[-44,-32],guangzhou:[-45,-15],shenzhen:[25,16],wuhan:[15,-17],chongqing:[18,20],chengdu:[-40,-14],beijing:[18,-10]};return `<svg class="map-svg" viewBox="0 0 780 430" role="img" aria-label="中国大陆十强城市地理分布，圆面积代表GDP；可通过下方城市排名选择">${[90,105,120].map(l=>{const p=project(l,54);return `<line class="map-grid" x1="${p[0]}" y1="15" x2="${p[0]}" y2="405"/>`;}).join('')}${[25,35,45].map(l=>{const p=project(73,l);return `<line class="map-grid" x1="25" y1="${p[1]}" x2="745" y2="${p[1]}"/>`;}).join('')}<g>${geoPaths()}</g>${CITIES.map(c=>{const [x,y]=project(c.lon,c.lat),[dx,dy]=offsets[c.id],r=state.metric==='gdp'?Math.sqrt(c.gdp/53926.71)*13:(typeof c.growth==='number'?Math.max(4,c.growth*2):4);return `<g class="bubble ${enabled.has(c.id)?'':'dim'}" transform="translate(${x},${y})" role="button" tabindex="${enabled.has(c.id)?0:-1}" aria-label="${c.name}，GDP ${fmt(c.gdp)}亿元，增速${typeof c.growth==='number'?c.growth+'%'+(c.id==='chongqing'?'（估计）':''):'待核验'}" aria-pressed="${state.city===c.id}" data-city="${c.id}"><title>${c.name} · ${state.metric==='gdp'?fmt(c.gdp/10000)+' 万亿元':(typeof c.growth==='number'?c.growth.toFixed(1)+'% 实际增速'+(c.id==='chongqing'?'（工作报告估计）':''):'增速待核验')}</title><circle class="halo" r="${r+7}"/><circle class="dot ${state.metric==='growth'&&typeof c.growth!=='number'?'unknown':''}" r="${r}"/><text x="${dx}" y="${dy}">${c.name}</text></g>`;}).join('')}<text x="40" y="370" fill="#71839b" font-size="12" letter-spacing="2">73° E</text><text x="644" y="370" fill="#71839b" font-size="12" letter-spacing="2">136° E</text></svg>`;}
function detail(){const c=profile(selected());return `<article class="panel detail"><div class="detail-top"><div><div class="city-en">${c.en}</div><h2 class="city-name">${c.name}</h2></div><span class="rank">NO. ${String(c.rank).padStart(2,'0')}</span></div><div class="region-label">${c.region} / ${c.tag.split(' · ')[0]}</div><h3 class="city-tag">${c.tag.split(' · ')[1]||c.tag}</h3><div class="detail-stat"><strong>${fmt(c.gdp/10000)}</strong><span>万亿元</span></div><div class="stat-meta">2024 年 GDP · 实际增长 ${typeof c.growth==='number'?c.growth.toFixed(1)+'%'+(c.id==='chongqing'?'（估计）':''):'待核验'}</div><div class="detail-divider"></div><div class="chip-row">${c.industry.map(t=>`<span class="chip">${t}</span>`).join('')}</div><p>${esc(c.summary)}</p>${['chongqing','hangzhou'].includes(c.id)?`<p class="caption" style="color:#9b7767;margin-top:0">${esc(c.evidenceNote)}</p>`:''}<div class="detail-explore"><button class="detail-facets" data-view="facets">城市切面</button><button class="detail-facets" data-open-map>手绘地图</button><button class="detail-facets" data-play-mode="blind">探索玩法</button></div><div class="detail-actions"><button class="primary" data-view="industry">深入了解${c.name}</button><button class="secondary" data-compare="${c.id}">${state.compare.includes(c.id)?'已加入对比':'加入对比'}</button></div></article>`;}
function rankings(){let cs=filtered();if(state.metric==='growth')cs=[...cs].sort((a,b)=>(b.growth??-1)-(a.growth??-1));const max=state.metric==='gdp'?53926.71:6;return `<section class="panel ranking-panel"><div class="panel-head"><h2>${state.metric==='gdp'?'经济体量':'实际增速'} / ${cs.length} 座城市</h2><small>${state.metric==='gdp'?'万亿元 · 现价':'同比 % · 不变价'}<span style="margin-left:14px">＋ 选择对比</span></small></div>${cs.length?'<div class="rank-grid">'+cs.map((c,i)=>`<div class="rank-item ${state.city===c.id?'active':''}"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><button class="text-btn" style="color:inherit;font-size:14px;padding:0" data-city="${c.id}">${c.name}</button><button class="rank-bar" data-city="${c.id}" aria-label="查看${c.name}"><i style="width:${(c[state.metric]??0)/max*100}%"></i></button><span class="rank-value">${state.metric==='gdp'?fmt(c.gdp/10000):(typeof c.growth==='number'?c.growth.toFixed(1)+'%'+(c.id==='chongqing'?'*':''):'待核验')}</span><button class="compare-check ${state.compare.includes(c.id)?'checked':''}" data-compare="${c.id}" aria-label="${state.compare.includes(c.id)?'移除':'加入'}${c.name}对比" aria-pressed="${state.compare.includes(c.id)}">${state.compare.includes(c.id)?'✓':'＋'}</button></div>`).join('')+'</div>':'<div class="empty">没有匹配的城市。试试其他产业或城市群。</div>'}<p class="caption" style="margin:15px 25px 0">${state.metric==='growth'?'按实际增速排序；* 重庆为工作报告估计，杭州暂缺已核验增速。':'重庆、杭州总量采用证据较弱的二手资料，合计仅作暂定对照。'}</p></section>`;}
function comparison(){const cs=state.compare.map(id=>CITIES.find(c=>c.id===id));return `<section class="panel comparison"><div class="comparison-top"><h2>把城市放在一起看</h2><small class="caption">最多 4 城</small></div><div class="comparison-chips">${cs.map(c=>`<button class="remove-chip" data-compare="${c.id}" aria-label="移除${c.name}对比">${c.name} ×</button>`).join('')}</div>${cs.length?`<div class="scroll-table"><table class="compare-table"><thead><tr><th>2024 年基准</th>${cs.map(c=>`<th>${c.name}</th>`).join('')}</tr></thead><tbody><tr><th>GDP / 万亿元</th>${cs.map(c=>`<td>${fmt(c.gdp/10000)}</td>`).join('')}</tr><tr><th>实际增速</th>${cs.map(c=>`<td>${typeof c.growth==='number'?c.growth.toFixed(1)+'%'+(c.id==='chongqing'?'（工作报告估计）':''):'待核验'}</td>`).join('')}</tr><tr><th>产业特征</th>${cs.map(c=>`<td>${c.industry.slice(0,2).join(' / ')}</td>`).join('')}</tr><tr><th>生活取舍</th>${cs.map(c=>`<td>${esc(profile(c).living?.[1]||'居住成本与通勤因片区而异')}</td>`).join('')}</tr></tbody></table></div>`:'<p class="caption" style="margin-top:20px">点击排名旁的 ＋，选择想比较的城市。</p>'}<p class="caption" style="margin:15px 0 0">重庆为省级直辖市，包含较大农村及山区范围；城市 GDP 总量不能直接代表个人收入或生活质量。</p></section>`;}
function overview(){return `<div class="overview-grid"><section class="panel map-panel"><div class="panel-head"><h2>经济版图</h2><small>CHINA / 2024</small></div><div class="map-top-stats"><div><b>≈ ${fmt(CITIES.reduce((s,c)=>s+c.gdp,0)/10000)}</b><small>十城 GDP 合计 / 万亿元</small></div><div><b>5 <span style="font-size:14px;color:#8f9eb3">个</span></b><small>主要城市群</small></div></div>${map()}<div class="map-bottom"><span class="legend"><i></i> ${state.metric==='gdp'?'圆面积随 GDP 变化':'圆半径随增速变化 · 空心为待核验'}</span><span>仅显示十城 · 地理位置示意</span></div></section>${detail()}</div>${rankings()}${comparison()}`;}
function render(){const [name,title,sub]=views[state.view];$('#search').placeholder=state.view==='facets'?'搜索城市 / 医院 / 场馆':'搜索城市 / 产业';$('label[for="search"]').textContent=state.view==='facets'?'搜索城市或代表资源':'搜索城市或产业';$('#breadcrumb').textContent='中国 / '+name;$('#page-title').innerHTML=title+'<span>。</span>';$('#page-subtitle').textContent=sub;document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===state.view);n.setAttribute('aria-current',n.dataset.view===state.view?'page':'false');});document.querySelectorAll('[data-metric]').forEach(n=>{n.classList.toggle('selected',n.dataset.metric===state.metric);n.setAttribute('aria-pressed',n.dataset.metric===state.metric);});$('.view-tabs').style.visibility=state.view==='overview'?'visible':'hidden';$('.toolbar').style.display=['sources','play'].includes(state.view)?'none':'flex';$('#content').innerHTML=state.view==='overview'?overview():window.renderExtra?renderExtra(state.view):overview();if(state.view==='play')window.syncPlayTabs?.();}
function toggleCompare(id){if(!CITIES.some(c=>c.id===id))throw new Error('城市不存在');if(state.compare.includes(id))state.compare=state.compare.filter(v=>v!==id);else if(state.compare.length>=4){toast('最多对比 4 座城市，请先移除一座。');return;}else state.compare.push(id);render();}
document.addEventListener('click',e=>{const t=e.target.closest('[data-view],[data-city],[data-compare],[data-metric],[data-preset],[data-scenario]');if(!t)return;if(t.dataset.view)setView(t.dataset.view);else if(t.dataset.city)setCity(t.dataset.city);else if(t.dataset.compare)toggleCompare(t.dataset.compare);else if(t.dataset.metric){state.metric=t.dataset.metric;render();}else if(t.dataset.preset&&window.applyPreset)applyPreset(t.dataset.preset);else if(t.dataset.scenario){state.scenario=t.dataset.scenario;state.rate={low:2,base:4.5,high:7}[state.scenario];render();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g.bubble')){e.preventDefault();setCity(e.target.dataset.city);}});
$('#region').addEventListener('change',e=>{state.region=e.target.value;if(filtered().length&&!filtered().some(c=>c.id===state.city))state.city=filtered()[0].id;render();});$('#search').addEventListener('input',e=>{state.search=e.target.value;if(filtered().length&&!filtered().some(c=>c.id===state.city))state.city=filtered()[0].id;if(state.view==='facets')window.syncFacetSearch?.();render();});$('#method-btn').addEventListener('click',()=>setView('sources'));$('#footer-sources').addEventListener('click',()=>setView('sources'));window.addEventListener('hashchange',()=>{const [v,mode]=location.hash.slice(1).split('/');if(views[v]){state.view=v;if(v==='play'&&window.PLAY_MODES?.[mode])state.playMode=mode;render();}});
state.view=views[location.hash.slice(1).split('/')[0]]?location.hash.slice(1).split('/')[0]:'overview';render();
fetch('china-provinces.json').then(r=>{if(!r.ok)throw new Error('map');return r.json();}).then(d=>{geography=d;render();}).catch(()=>{});
